import React from "react";

export default function Profile() {

const user = JSON.parse(
localStorage.getItem("user")
);

return (

<div
style={{

minHeight:"100vh",

background:"#0f172a",

display:"flex",

justifyContent:"center",

alignItems:"center"

}}

>

<div

style={{

background:"white",

padding:"40px",

borderRadius:"20px",

width:"450px",

boxShadow:"0 10px 25px rgba(0,0,0,0.3)"

}}

>

<h1

style={{

textAlign:"center",

marginBottom:"30px",

color:"#2563eb"

}}

>

👤 My Profile

</h1>


<div style={{marginBottom:"20px"}}>

<h3>

Name

</h3>

<p>

{user?.name || "No Name"}

</p>

</div>



<div style={{marginBottom:"20px"}}>

<h3>

Email

</h3>

<p>

{user?.email || "No Email"}

</p>

</div>



<div style={{marginBottom:"20px"}}>

<h3>

Role

</h3>

<p>

{user?.role || "Student"}

</p>

</div>



<div style={{marginBottom:"20px"}}>

<h3>

Password

</h3>

<p>

********

</p>

</div>


<button

style={{

width:"100%",

padding:"12px",

background:"#2563eb",

color:"white",

border:"none",

borderRadius:"8px",

cursor:"pointer"

}}

onClick={()=>{

localStorage.removeItem("user");

window.location.href="/login";

}}

>

Logout

</button>


</div>

</div>

)

}
